# <<< SPEC

# >>> HINTS
# <<< HINTS

# >>> CHOICES
if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_command() {
    if _argc_util_has_path_prefix; then
        _argc_util_comp_path
        return 0
    fi
    _argc_util_comp_command
}

_choice_command_args() {
    if [[ "${#argc__positionals[@]}" -lt 2 ]]; then
        _choice_command
    else
        _argc_util_comp_subcommand 0
    fi
}

_choice_compile_target() {
    _helper_meson_target_names "${argc_C:-.}"
}

_choice_configure_define() {
    _argc_util_mode_kv =
    local builddir="${argc_builddir:-.}"
    [[ -f "$builddir/meson-private/coredata.dat" ]] || return 0
    if [[ -z "$argc__kv_prefix" ]]; then
        meson introspect --buildoptions "$builddir" 2>/dev/null |
            jq -b -r 'limit(500; .[] | .name // empty)' 2>/dev/null
    else
        meson introspect --buildoptions "$builddir" 2>/dev/null |
            jq -b -r --arg key "$argc__kv_key" \
                'limit(500; .[] | select(.name == $key) | .choices[]? // empty)' 2>/dev/null
    fi
}

_choice_configure_unset() {
    local builddir="${argc_builddir:-.}"
    [[ -f "$builddir/meson-private/coredata.dat" ]] || return 0
    meson introspect --buildoptions "$builddir" 2>/dev/null |
        jq -b -r 'limit(500; .[] | select(.name | contains(":")) | .name)' 2>/dev/null
}

_choice_install_tag() {
    local builddir="${argc_C:-.}"
    [[ -f "$builddir/meson-private/coredata.dat" ]] || return 0
    meson introspect --install-plan "$builddir" 2>/dev/null |
        jq -b -r 'limit(500; .targets[]? | .tag // empty)' 2>/dev/null
}

_choice_reprotest_mesonargs() {
    local completion="$ARGC_COMPLETIONS_ROOT/completions/meson.sh"
    local start=$((argc__cmd_arg_index + 1))
    local -a args=(meson setup "${argc__args[@]:$start}")
    [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$completion" ]] || return 0
    [[ ${#args[@]} -gt 2 ]] || args+=("")
    args[-1]="$ARGC_LAST_ARG"
    argc --argc-compgen generic "$completion" "${args[@]}"
}

_choice_rewrite_id() {
    case "${argc_function_type:-}" in
    project) printf '/\n' ;;
    target) _helper_meson_target_ids . ;;
    dependency) _helper_meson_dependency_names . ;;
    esac
}

_choice_rewrite_target() {
    local builddir=.
    [[ -f "$builddir/meson-private/coredata.dat" ]] || return 0
    meson introspect --targets "$builddir" 2>/dev/null |
        jq -b -r 'limit(500; .[] | (.name // empty), (.id // empty))' 2>/dev/null
}

_choice_source_subproject() {
    _helper_meson_source_subprojects "${argc_sourcedir:-.}"
}

_choice_subproject() {
    local builddir="${argc_builddir:-${argc_C:-.}}"
    [[ -f "$builddir/meson-private/coredata.dat" ]] || return 0
    meson introspect --projectinfo "$builddir" 2>/dev/null |
        jq -b -r 'limit(500; .subprojects[]? | .name // empty)' 2>/dev/null
}

_choice_test_name() {
    local builddir="${argc_C:-.}"
    [[ -f "$builddir/meson-private/coredata.dat" ]] || return 0
    meson introspect --tests "$builddir" 2>/dev/null |
        jq -b -r 'limit(500; .[] | .name // empty)' 2>/dev/null
}

_choice_test_suite() {
    local builddir="${argc_C:-.}"
    [[ -f "$builddir/meson-private/coredata.dat" ]] || return 0
    meson introspect --tests "$builddir" 2>/dev/null |
        jq -b -r 'limit(500; .[] | .suite[]? | split(":")[-1] | select(length > 0))' 2>/dev/null
}

_choice_wrap_project() {
    _argc_util_cache 3600 _helper_wrap_project_uncached
}

_helper_meson_dependency_names() {
    local builddir="$1"
    [[ -f "$builddir/meson-private/coredata.dat" ]] || return 0
    meson introspect --dependencies "$builddir" 2>/dev/null |
        jq -b -r 'limit(500; .[] | .name // empty)' 2>/dev/null
}

_helper_meson_source_subprojects() {
    local sourcedir="$1" entry name
    local subprojects_dir="$sourcedir/subprojects"
    [[ -d "$subprojects_dir" ]] || return 0
    for entry in "$subprojects_dir"/*; do
        [[ -e "$entry" ]] || continue
        name="${entry##*/}"
        if [[ -d "$entry" && -f "$entry/meson.build" ]]; then
            printf '%s\n' "$name"
        elif [[ -f "$entry" && "$name" == *.wrap ]]; then
            printf '%s\n' "${name%.wrap}"
        fi
    done
}

_helper_meson_target_ids() {
    local builddir="$1"
    [[ -f "$builddir/meson-private/coredata.dat" ]] || return 0
    meson introspect --targets "$builddir" 2>/dev/null |
        jq -b -r 'limit(500; .[] | .id // empty)' 2>/dev/null
}

_helper_meson_target_names() {
    local builddir="$1"
    [[ -f "$builddir/meson-private/coredata.dat" ]] || return 0
    meson introspect --targets "$builddir" 2>/dev/null |
        jq -b -r 'limit(500; .[] | .name // empty)' 2>/dev/null
}

_helper_wrap_project_uncached() {
    meson wrap list 2>/dev/null | sed -n '1,500p'
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
